// Risk flags for each task. Counting happens here, not in the AI model.
const TODAY = new Date();
TODAY.setHours(0, 0, 0, 0);

const pick = (obj, keys) => {
  for (const k of keys) {
    if (obj[k] !== undefined && obj[k] !== null && obj[k] !== '') return obj[k];
  }
  return '';
};

const toText = (v) => {
  if (Array.isArray(v)) return v.map(x => (x && x.name) || x).join(', ');
  if (v && typeof v === 'object') return v.name || '';
  return String(v || '').trim();
};

const toDate = (v) => {
  if (!v) return null;
  const s = typeof v === 'object' ? (v.start || '') : String(v);
  if (!s) return null;
  const d = new Date(s.slice(0, 10) + 'T00:00:00');
  return isNaN(d) ? null : d;
};

return $input.all().map(item => {
  const j = item.json;

  const status   = toText(pick(j, ['property_status']));
  const assignee = toText(pick(j, ['property_assignee']));
  const notes    = toText(pick(j, ['property_notes']));
  const sprint   = toText(pick(j, ['property_sprint']));
  const due      = toDate(pick(j, ['property_due_date', 'property_date']));
  const blockedFlag = pick(j, ['property_blocked']);

  const isDone = status === 'Done';
  const blocked =
    status === 'Blocked' ||
    blockedFlag === true || blockedFlag === 'true' ||
    notes.toUpperCase().includes('BLOCKED');

  const daysToDue = due ? Math.round((due - TODAY) / 86400000) : null;
  const overdue   = !isDone && due !== null && daysToDue < 0;
  const unassigned = !isDone && assignee === '';
  const dueSoon   = !isDone && due !== null && daysToDue >= 0 && daysToDue <= 7;

  const flags = [];
  if (blocked)    flags.push('BLOCKED');
  if (overdue)    flags.push('OVERDUE');
  if (unassigned) flags.push('UNASSIGNED');
  if (dueSoon)    flags.push('DUE_SOON');

  let risk = 'LOW';
  if (blocked && overdue) risk = 'HIGH';
  else if (blocked || overdue || unassigned) risk = 'MEDIUM';

  return {
    json: {
      task_id: toText(j.property_task_id),
      name: j.name,
      status,
      assignee: assignee || 'Unassigned',
      due_date: due ? (() => { const v = pick(j, ['property_due_date', 'property_date']); return String(typeof v === 'object' ? (v.start || '') : v).slice(0, 10); })() : null,
      sprint,
      notes,
      blocked,
      overdue,
      days_overdue: overdue ? Math.abs(daysToDue) : 0,
      unassigned,
      due_soon: dueSoon,
      flags,
      risk_level: risk,
      url: j.url,
    },
  };
});

// Compares this week's tasks against saved history.
// All counting is done in code, not by the AI model.

// If you did NOT rename your first Code node, change this to 'Code in JavaScript'
const RISK_NODE = 'Risk Flags';

const history = $input.all().map(i => {
  const j = i.json;
  return {
    week:    j.week    ?? j.property_week,
    task_id: j.task_id ?? j.property_task_id,
    status:  j.status  ?? j.property_status,
    sprint:  j.sprint  ?? j.property_sprint,
  };
});
const current = $(RISK_NODE).all().map(i => i.json);

function isoWeek(date) {
  const d = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()));
  const dayNum = d.getUTCDay() || 7;
  d.setUTCDate(d.getUTCDate() + 4 - dayNum);
  const yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
  const week = Math.ceil((((d - yearStart) / 86400000) + 1) / 7);
  return `${d.getUTCFullYear()}-W${String(week).padStart(2, '0')}`;
}
const thisWeek = isoWeek(new Date());

return current.map(task => {
  // Past entries for this task, excluding this week so re-runs don't double count
  const past = history
    .filter(h => h.task_id === task.task_id && h.week !== thisWeek)
    .sort((a, b) => String(a.week).localeCompare(String(b.week)));

  const timeline = [
    ...past.map(h => ({ week: h.week, status: h.status, sprint: h.sprint })),
    { week: thisWeek, status: task.status, sprint: task.sprint },
  ];

  // Count consecutive weeks, ending now, with the same status
  let streak = 0;
  const streakEntries = [];
  for (let i = timeline.length - 1; i >= 0; i--) {
    if (timeline[i].status === task.status) {
      streak++;
      streakEntries.unshift(timeline[i]);
    } else break;
  }

  const sprints = [...new Set(streakEntries.map(e => e.sprint))];
  const stuck =
    (task.status === 'Blocked' && streak >= 2) ||
    (task.status === 'In Progress' && streak >= 3);

  const flags = [...task.flags];
  if (stuck) flags.push('STUCK');

  let risk = task.risk_level;
  if (stuck && risk === 'LOW') risk = 'MEDIUM';
  if (stuck && task.status === 'Blocked' && task.overdue) risk = 'HIGH';

  return {
    json: {
      ...task,
      week: thisWeek,
      weeks_in_status: streak,
      stuck,
      sprints_spanned: sprints,
      stuck_over_one_sprint: stuck && sprints.length > 1,
      flags,
      risk_level: risk,
      history: timeline.map(t => `${t.week}: ${t.status}`).join(' | '),
    },
  };
});

// Packs all task results into ONE summary object for the report writer.
const tasks = $input.all().map(i => i.json);

const slim = t => ({
  task_id: t.task_id, name: t.name, status: t.status,
  assignee: t.assignee, due_date: t.due_date,
  days_overdue: t.days_overdue, weeks_in_status: t.weeks_in_status,
  notes: t.notes, flags: t.flags, risk_level: t.risk_level,
});

// Week-over-week movement, read from each task's history string
const moved = [];
let doneLastWeek = 0;
for (const t of tasks) {
  const parts = (t.history || '').split(' | ');
  const prev = parts.length > 1 ? parts[parts.length - 2].split(': ')[1] : null;
  if (prev === 'Done') doneLastWeek++;
  if (prev && prev !== t.status) {
    moved.push({ task_id: t.task_id, name: t.name, from: prev, to: t.status });
  }
}

const count = s => tasks.filter(t => t.status === s).length;

return [{
  json: {
    week: tasks[0]?.week,
    report_date: new Date().toISOString().slice(0, 10),
    total_tasks: tasks.length,
    status_counts: {
      done: count('Done'), in_progress: count('In Progress'),
      blocked: count('Blocked'), to_do: count('To Do'),
    },
    done_last_week: doneLastWeek,
    moved_since_last_week: moved,
    high_risk: tasks.filter(t => t.risk_level === 'HIGH').map(slim),
    medium_risk: tasks.filter(t => t.risk_level === 'MEDIUM').map(slim),
    blocked: tasks.filter(t => t.blocked).map(slim),
    overdue: tasks.filter(t => t.overdue).map(slim),
    unassigned: tasks.filter(t => t.unassigned).map(slim),
    due_within_7_days: tasks.filter(t => t.due_soon).map(slim),
    stuck_more_than_one_sprint: tasks.filter(t => t.stuck_over_one_sprint).map(slim),
    stuck_any: tasks.filter(t => t.stuck).map(slim),
  },
}];
